description:
Implement a hook that wraps a function with `useCallback` so it returns the same function reference when `deps` haven't changed, and a new reference when they have.

**Example:**
```tsx
const handleClick = useCallbackStable(() => console.log(count), [count]);
// handleClick reference stays stable while count is unchanged
```

starter_code:
import { useCallback } from 'react';

export function useCallbackStable<T extends (...args: any[]) => any>(fn: T, deps: any[]): T {
  // your code here
}

test_suite:
test('returns the wrapped function', () => {
  const fn = vi.fn();
  const { result } = renderHook(() => useCallbackStable(fn, []));
  result.current();
  expect(fn).toHaveBeenCalledTimes(1);
});

test('returns same reference when deps unchanged', () => {
  const fn = () => {};
  const { result, rerender } = renderHook(() => useCallbackStable(fn, [1, 2]));
  const first = result.current;
  rerender();
  expect(result.current).toBe(first);
});

test('returns new reference when deps change', () => {
  let dep = 1;
  const { result, rerender } = renderHook(() => useCallbackStable(() => dep, [dep]));
  const first = result.current;
  dep = 2;
  rerender();
  expect(result.current).not.toBe(first);
});

test('passes arguments to underlying function', () => {
  const fn = vi.fn((x: number) => x * 2);
  const { result } = renderHook(() => useCallbackStable(fn, []));
  const val = result.current(5);
  expect(val).toBe(10);
});

// __hidden__
test('stable reference with empty deps across multiple rerenders', () => {
  const fn = () => 42;
  const { result, rerender } = renderHook(() => useCallbackStable(fn, []));
  const first = result.current;
  rerender();
  rerender();
  rerender();
  expect(result.current).toBe(first);
});

solution:
import { useCallback } from 'react';

export function useCallbackStable<T extends (...args: any[]) => any>(fn: T, deps: any[]): T {
  // eslint-disable-next-line react-hooks/exhaustive-deps
  return useCallback(fn, deps);
}
